'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token='',offset=0,lastFilters='',pageItems=[];
const status=s=>$('#liveStatus').textContent=s;
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json',...(options.headers||{})}});if(!r.ok){if(r.status===401){logout();throw Error('Mã workspace không hợp lệ.')}throw Error(`Backend trả lỗi ${r.status}. Kiểm tra cấu hình và dữ liệu nhập.`)}return r}
function logout(){token='';$('#workspaceToken').value='';$('#authenticated').hidden=true;$('#login').hidden=false;$('#logout').hidden=true;$('#liveResults').replaceChildren();$('#jobList').replaceChildren();$('#sourceStates').replaceChildren();$('#liveLogs').textContent='';status('Đã ngắt kết nối. Mã không được lưu trên trình duyệt.')}
async function action(fn,button){if(button)button.disabled=true;try{await fn()}catch(e){status(e.message)}finally{if(button)button.disabled=false}}
async function refresh(){const [s,j,r,u]=await Promise.all(['sources','jobs','runs','usage'].map(async p=>(await api(p)).json()));$('#sourceStates').innerHTML=s.sources.map(v=>`<p class="notice"><strong>${esc(v.platform)}</strong> · ${v.credential_configured?'Đã cấu hình token, quyền chưa xác minh':'Chưa cấu hình token'}<br>${esc(v.scope)}</p>`).join('')+`<p class="notice">X: trần đọc cục bộ ${s.x_daily_read_cap} bài/ngày UTC · ${s.page_size} bài/trang. Trần cục bộ không thay thế giới hạn chi tiêu ở X.</p>`;$('#jobList').innerHTML=j.items.map(v=>`<article class="job"><strong>#${v.id} · ${esc(v.platform)} · ${esc(v.query)}</strong><p>${v.enabled?'Lịch bật':'Lịch tắt'} · ${v.interval_seconds}s · Lỗi: ${esc(v.last_error||'không')}<br>Lượt sớm nhất: ${v.next_run?esc(new Date(v.next_run*1000).toLocaleString('vi-VN')):'sẵn sàng'}</p><button data-run="${v.id}">Chạy 1 trang</button><button data-toggle="${v.id}" data-enabled="${v.enabled?0:1}">${v.enabled?'Tắt lịch':'Bật lịch'}</button></article>`).join('')||'<p class="notice">Chưa có truy vấn.</p>';$('#liveLogs').textContent=JSON.stringify({runs:r.items,usage:u},null,2)}
function filters(){return new URLSearchParams({q:$('#liveQ').value,exclude:$('#liveExclude').value,platform:$('#livePlatform').value,min_engagement:$('#liveMin').value,days:$('#liveDays').value,saved:$('#onlySaved').checked}).toString()}
function safeURL(url){try{const u=new URL(url);return u.protocol==='https:'&&['x.com','www.facebook.com','facebook.com','www.threads.net','www.threads.com','threads.net','threads.com'].includes(u.hostname)?esc(u.href):''}catch{return ''}}
async function search(next=false){if(!next){offset=0;lastFilters=filters()}const result=await(await api('posts?'+lastFilters+'&limit=100&offset='+offset)).json();pageItems=result.items;$('#liveCount').textContent=`${result.total} bài · Trang ${Math.floor(offset/100)+1}`;$('#liveResults').innerHTML=result.items.map(p=>`<article class="liveresult"><strong>${esc(p.author||'Không có tác giả')} · ${esc(p.platform)}</strong><p>${esc(p.text)}</p><small>${esc(p.published_at)} · ♡ ${esc(p.likes??'—')} · Bình luận ${esc(p.comments??'—')} · Chia sẻ ${esc(p.shares??'—')}<br>Thu thập: ${esc(new Date(p.collected_at*1000).toLocaleString('vi-VN'))}</small><p>${safeURL(p.url)?`<a href="${safeURL(p.url)}" target="_blank" rel="noopener noreferrer">Mở bài gốc ↗</a>`:''} <button data-bookmark="${p.id}" data-saved="${p.saved?0:1}">${p.saved?'Bỏ lưu':'Lưu bài'}</button></p></article>`).join('')||'<p class="notice">Chưa có bài phù hợp. Kiểm tra truy vấn thu thập và nhật ký chạy.</p>';$('#loadMore').hidden=offset+result.items.length>=result.total}
$('#login').onsubmit=e=>{e.preventDefault();action(async()=>{token=$('#workspaceToken').value;$('#workspaceToken').value='';await refresh();$('#authenticated').hidden=false;$('#login').hidden=true;$('#logout').hidden=false;await search();status('Đã kết nối backend. Dữ liệu được lưu chung trên máy chủ.')},e.submitter)};$('#logout').onclick=logout;
$('#jobForm').onsubmit=e=>{e.preventDefault();action(async()=>{const body={platform:$('#jobPlatform').value,query:$('#jobQuery').value,page_id:$('#pageId').value,interval_seconds:Number($('#jobInterval').value)};await api('jobs',{method:'POST',body:JSON.stringify(body)});await refresh();status('Đã tạo truy vấn. Lịch đang tắt; chưa thu thập.')},e.submitter)};
$('#refresh').onclick=e=>action(refresh,e.currentTarget);$('#liveSearch').onsubmit=e=>{e.preventDefault();action(()=>search(),e.submitter)};$('#loadMore').onclick=e=>action(async()=>{offset+=100;await search(true)},e.currentTarget);
$('#liveExport').onclick=e=>action(async()=>{const r=await api('reports.csv?'+filters());const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='social-radar-live.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status(r.headers.get('X-Report-Truncated')==='true'?'Đã xuất 10.000 dòng đầu. Thu hẹp bộ lọc để lấy đủ dữ liệu.':'Đã xuất báo cáo từ dữ liệu đã thu thập.')},e.currentTarget);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.run)action(async()=>{const r=await(await api(`jobs/${b.dataset.run}/run`,{method:'POST'})).json();await refresh();await search();status(({success:`Đã thu thập ${r.fetched??0} bài, thêm mới ${r.inserted??0} bài.`,deferred:'Chưa đến lượt chạy. Đợi hết chu kỳ hoặc thời gian thử lại.',missing_credentials:'Chưa cấu hình token nguồn trên máy chủ.',daily_read_cap:'Đã chạm giới hạn đọc dự trù trong ngày UTC.',facebook_configuration_required:'Cần cấu hình version API và Page ID hợp lệ.',error:`Nguồn trả lỗi: ${r.error_code||'không xác định'}. ${r.paused?'Lịch đã tắt.':'Hệ thống sẽ chờ trước khi thử lại.'}`})[r.status]||'Chưa thể chạy. Kiểm tra nhật ký.')},b);if(b.dataset.toggle)action(async()=>{await api(`jobs/${b.dataset.toggle}`,{method:'PATCH',body:JSON.stringify({enabled:b.dataset.enabled==='1'})});await refresh();status(b.dataset.enabled==='1'?'Đã bật lịch. Cần tiến trình worker đang chạy.':'Đã tắt lịch.')},b);if(b.dataset.bookmark)action(async()=>{await api(`posts/${b.dataset.bookmark}/bookmark`,{method:'PUT',body:JSON.stringify({saved:b.dataset.saved==='1'})});await search(true)},b)});
